import numpy as np
from sklearn.cluster import DBSCAN
import torch

class MyPreprocessor:
    def __init__(self):
        self.mean_ = None
        self.std_ = None

    def _raw_reshape(self, data):
        return data

    def make_loader_cfg(self):
        return None

    def fit(self, events):
        total_hits = 0
        sum_ = np.zeros(4, dtype=np.float64)
        sumsq = np.zeros(4, dtype=np.float64)
        for evt in events:
            X = np.column_stack((evt["hit_r"], evt["hit_theta"], evt["hit_z"], evt["layer_id"]))  # (Ni,4)
            sum_ += X.sum(axis=0)
            sumsq += (X * X).sum(axis=0)
            total_hits += X.shape[0]
        mean = sum_ / total_hits
        var = sumsq / total_hits - mean**2
        std = np.sqrt(np.maximum(var, 0) + 1e-6)
        self.mean_ = torch.tensor(mean, dtype=torch.float32)
        self.std_ = torch.tensor(std, dtype=torch.float32)
        return self

    def transform(self, data):
        # data: torch.Tensor (Ni,4)
        return (data - self.mean_) / self.std_  # (Ni,4)

def make_preprocessor():
    return MyPreprocessor()

class HitClassifier(torch.nn.Module):
    def __init__(self, in_features):
        super().__init__()

    def forward(self, batch):
        preds = []
        for hits, _ in batch:
            # hits: torch.Tensor (Ni, F)
            X = hits.cpu().numpy()  # (Ni, F)
            labels = DBSCAN(eps=0.5, min_samples=4).fit_predict(X)  # (Ni,)
            preds.append(torch.from_numpy(labels).to(hits.device))  # (Ni,)
        return preds

def make_model(in_features):
    return HitClassifier(in_features)

